css:
:root{
  --paper:#FBFAFE;
  --ink:#16122E;
  --muted:#5E5A78;
  --line:#E4E0F2;
  --violet:#35208F;
  --violet-deep:#1E1160;
  --aqua:#1FC2D8;
  --aqua-soft:#DDF6FA;
  --lav:#F0ECFC;
  --saffron:#FFB11F;
  --radius:14px;
  --max:1180px;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'DM Sans',system-ui,sans-serif;color:var(--ink);background:var(--paper);line-height:1.6;font-size:17px;-webkit-font-smoothing:antialiased}
h1,h2,h3{font-family:'Bricolage Grotesque',sans-serif;line-height:1.08;letter-spacing:-.02em}
a{color:inherit;text-decoration:none}
img{max-width:100%;display:block}
.wrap{max-width:var(--max);margin:0 auto;padding:0 24px}
:focus-visible{outline:3px solid var(--aqua);outline-offset:3px;border-radius:6px}

/* top strip */
.strip{background:var(--violet-deep);color:#CFC8F5;font-size:13.5px}
.strip .wrap{display:flex;gap:28px;justify-content:space-between;align-items:center;padding-top:9px;padding-bottom:9px;flex-wrap:wrap}
.strip span{display:inline-flex;gap:8px;align-items:center}
.strip a:hover{color:#fff}

/* nav */
header.nav{position:sticky;top:0;z-index:50;background:rgba(251,250,254,.88);backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}
.nav .wrap{display:flex;align-items:center;justify-content:space-between;height:76px;gap:24px}
.logo{display:flex;align-items:center;gap:12px;font-family:'Bricolage Grotesque';font-weight:800;font-size:22px;letter-spacing:-.02em}
.logo-mark{width:38px;height:38px;border-radius:10px;background:linear-gradient(140deg,var(--violet),var(--aqua));display:grid;place-items:center;color:#fff;font-size:20px}
.logo small{display:block;font:500 10.5px 'DM Sans';letter-spacing:.06em;color:var(--muted);margin-top:-2px}
nav ul{display:flex;gap:30px;list-style:none;font-weight:500;font-size:15.5px}
nav a{padding:6px 0;border-bottom:2px solid transparent;transition:border-color .2s,color .2s}
nav a:hover{border-color:var(--aqua);color:var(--violet)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:14px 24px;border-radius:999px;font-weight:600;font-size:16px;border:2px solid transparent;cursor:pointer;transition:transform .15s,background .2s,box-shadow .2s;font-family:inherit}
.btn:hover{transform:translateY(-2px)}
.btn-primary{background:var(--violet);color:#fff;box-shadow:0 8px 22px -8px rgba(53,32,143,.6)}
.btn-primary:hover{background:var(--violet-deep)}
.btn-ghost{border-color:var(--ink);color:var(--ink);background:transparent}
.btn-ghost:hover{background:var(--ink);color:#fff}
.btn-aqua{background:var(--aqua);color:var(--violet-deep)}
.btn-aqua:hover{background:#fff}
.menu-btn{display:none;background:none;border:2px solid var(--ink);border-radius:10px;padding:8px 12px;font-weight:600;font-family:inherit;cursor:pointer}

/* hero */
.hero{padding:76px 0 90px;position:relative;overflow:hidden}
.hero::before{content:"";position:absolute;right:-180px;top:-160px;width:620px;height:620px;border-radius:50%;background:radial-gradient(circle,var(--aqua-soft),transparent 68%);z-index:-1}
.hero .wrap{display:grid;grid-template-columns:1.05fr 1fr;gap:56px;align-items:center}
.badge{display:inline-flex;align-items:center;gap:10px;background:var(--lav);color:var(--violet);padding:7px 14px;border-radius:999px;font-weight:600;font-size:14px;margin-bottom:24px}
.badge i{width:8px;height:8px;border-radius:50%;background:var(--saffron);display:block}
h1{font-size:clamp(40px,5.6vw,68px);font-weight:800;margin-bottom:22px}
h1 em{font-style:normal;color:var(--violet)}
.lead{font-size:19px;color:var(--muted);max-width:520px;margin-bottom:32px}
.cta-row{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:38px}
.proof{display:flex;gap:30px;flex-wrap:wrap;font-size:14.5px;color:var(--muted)}
.proof b{display:block;font:700 22px 'Bricolage Grotesque';color:var(--ink)}

/* Tally-like voucher mock */
.voucher{background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:0 40px 80px -30px rgba(30,17,96,.35);overflow:hidden;transform:rotate(1.2deg)}
.v-bar{display:flex;justify-content:space-between;align-items:center;background:var(--violet-deep);color:#fff;padding:12px 18px;font:500 13px 'JetBrains Mono',monospace}
.v-bar span:last-child{color:var(--aqua)}
.v-body{padding:20px 22px;font:400 13.5px 'JetBrains Mono',monospace}
.v-head{display:flex;justify-content:space-between;margin-bottom:14px;color:var(--muted)}
.v-head b{color:var(--ink)}
.v-row{display:grid;grid-template-columns:1fr 70px 100px;gap:10px;padding:9px 0;border-bottom:1px dashed var(--line)}
.v-row.h{color:var(--muted);font-size:12px;border-bottom:1px solid var(--line)}
.v-row span:nth-child(n+2){text-align:right}
.v-tax{background:var(--aqua-soft);margin:12px -22px 0;padding:10px 22px;display:flex;justify-content:space-between;color:var(--violet-deep)}
.v-total{display:flex;justify-content:space-between;padding-top:14px;font:700 20px 'Bricolage Grotesque'}
.v-chip{position:absolute;background:var(--saffron);color:#2A1B00;font:700 13px 'DM Sans';padding:9px 14px;border-radius:999px;box-shadow:0 10px 24px -8px rgba(0,0,0,.35)}
.v-wrap{position:relative}
.v-chip.a{left:-22px;bottom:70px;transform:rotate(-5deg)}
.v-chip.b{right:-8px;top:-18px;background:var(--aqua);color:var(--violet-deep);transform:rotate(4deg)}

/* sections */
section{padding:92px 0}
.sec-head{max-width:640px;margin-bottom:48px}
.sec-head h2{font-size:clamp(32px,4vw,46px);margin-bottom:14px;font-weight:700}
.sec-head p{color:var(--muted);font-size:18px}

/* products bento */
.bento{display:grid;grid-template-columns:repeat(6,1fr);grid-auto-rows:minmax(230px,auto);gap:18px}
.tile{position:relative;border-radius:22px;padding:30px;overflow:hidden;display:flex;flex-direction:column;justify-content:flex-end;transition:transform .25s}
.tile:hover{transform:translateY(-4px)}
.tile h3{font-size:26px;margin-bottom:8px}
.tile p{font-size:15.5px;opacity:.85;max-width:340px}
.tile .go{margin-top:16px;font-weight:600;font-size:15px;display:inline-flex;gap:6px}
.t-server{grid-column:span 3;grid-row:span 2;background:linear-gradient(160deg,var(--violet) 0%,var(--violet-deep) 100%);color:#fff}
.t-server h3{font-size:34px}
.t-lic{grid-column:span 3;background:var(--lav)}
.t-up{grid-column:span 1;background:var(--aqua-soft)}
.t-srv{grid-column:span 2;background:#fff;border:1px solid var(--line)}
.t-up{grid-column:span 1}
.rack{position:absolute;right:26px;top:26px;display:grid;gap:8px;width:170px}
.rack div{height:30px;border-radius:8px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.2);position:relative}
.rack div::after{content:"";position:absolute;right:10px;top:11px;width:8px;height:8px;border-radius:50%;background:var(--aqua);box-shadow:0 0 10px var(--aqua)}
.key{position:absolute;right:26px;top:24px;font:500 13px 'JetBrains Mono';color:var(--violet);background:#fff;border:1px dashed var(--violet);padding:10px 14px;border-radius:10px}

/* services */
.services{background:var(--ink);color:#fff}
.services .sec-head p{color:#B9B4D6}
.svc-grid{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid #38325F}
.svc{padding:32px 30px 34px 0;border-bottom:1px solid #38325F;transition:background .2s}
.svc:not(:nth-child(3n+1)){padding-left:30px;border-left:1px solid #38325F}
.svc h3{font-size:22px;margin-bottom:8px}
.svc p{color:#B9B4D6;font-size:15.5px}
.svc:hover h3{color:var(--aqua)}

/* why */
.why-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:0}
.why{padding:6px 28px 6px 0}
.why + .why{border-left:1px solid var(--line);padding-left:28px}
.why .ic{width:48px;height:48px;border-radius:12px;background:var(--lav);display:grid;place-items:center;font-size:22px;margin-bottom:18px}
.why h3{font-size:21px;margin-bottom:8px}
.why p{color:var(--muted);font-size:15.5px}

/* industries */
.ind{background:var(--lav)}
.chips{display:flex;flex-wrap:wrap;gap:12px}
.chip{background:#fff;border:1px solid var(--line);padding:14px 24px;border-radius:999px;font:600 18px 'Bricolage Grotesque';transition:background .2s,color .2s,transform .2s}
.chip:hover{background:var(--violet);color:#fff;transform:translateY(-2px)}

/* trial */
.trial{padding:0 0 92px}
.trial-box{background:linear-gradient(120deg,var(--violet-deep),var(--violet));color:#fff;border-radius:28px;padding:60px;display:grid;grid-template-columns:1.3fr 1fr;gap:40px;align-items:center;position:relative;overflow:hidden}
.trial-box::after{content:"₹";position:absolute;right:-30px;bottom:-110px;font:800 380px 'Bricolage Grotesque';color:rgba(255,255,255,.05);line-height:1}
.trial-box h2{font-size:clamp(32px,4vw,46px);margin-bottom:14px}
.trial-box p{color:#CFC8F5;margin-bottom:28px;max-width:520px}
.stat{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);border-radius:16px;padding:20px 24px;margin-bottom:14px;position:relative;z-index:1}
.stat b{font:800 38px 'Bricolage Grotesque';display:block;line-height:1}
.stat span{color:#CFC8F5;font-size:14.5px}

/* customers */
.logos{display:grid;grid-template-columns:repeat(6,1fr);gap:16px}
.logo-ph{height:84px;border:1.5px dashed var(--line);border-radius:14px;display:grid;place-items:center;color:var(--muted);font-size:13.5px;text-align:center;padding:8px;background:#fff}

/* faq */
.faq-wrap{display:grid;grid-template-columns:1fr 1.4fr;gap:60px;align-items:start}
details{border-bottom:1px solid var(--line);padding:20px 0}
details:first-of-type{border-top:1px solid var(--line)}
summary{list-style:none;cursor:pointer;font:600 19px 'Bricolage Grotesque';display:flex;justify-content:space-between;gap:20px;align-items:center}
summary::-webkit-details-marker{display:none}
summary::after{content:"+";font-size:26px;color:var(--violet);transition:transform .25s}
details[open] summary::after{transform:rotate(45deg)}
details p{margin-top:12px;color:var(--muted);max-width:620px}

/* contact */
.contact{background:var(--lav)}
.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:56px}
.info li{list-style:none;display:flex;gap:14px;margin-bottom:18px;color:var(--muted)}
.info b{color:var(--ink);display:block}
form{background:#fff;border-radius:22px;padding:32px;border:1px solid var(--line);display:grid;gap:16px}
label{font-weight:600;font-size:14.5px;display:grid;gap:6px}
input,select,textarea{font:inherit;padding:13px 14px;border:1.5px solid var(--line);border-radius:10px;background:var(--paper);color:var(--ink)}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--violet);box-shadow:0 0 0 3px rgba(53,32,143,.15)}
.two{display:grid;grid-template-columns:1fr 1fr;gap:16px}

/* footer */
footer{background:var(--ink);color:#B9B4D6;padding:70px 0 26px;font-size:15px}
.foot{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:40px;margin-bottom:46px}
footer h4{color:#fff;font:700 17px 'Bricolage Grotesque';margin-bottom:14px}
footer li{list-style:none;margin-bottom:9px}
footer a:hover{color:var(--aqua)}
.copy{border-top:1px solid #38325F;padding-top:22px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px;font-size:13.5px}

.wa{position:fixed;right:22px;bottom:22px;width:58px;height:58px;border-radius:50%;background:#25D366;display:grid;place-items:center;box-shadow:0 12px 28px -8px rgba(0,0,0,.4);z-index:60;font-size:28px;transition:transform .2s}
.wa:hover{transform:scale(1.08)}

/* responsive */
@media(max-width:960px){
  .hero .wrap,.trial-box,.faq-wrap,.contact-grid{grid-template-columns:1fr}
  .voucher{transform:none}
  .bento{grid-template-columns:repeat(2,1fr)}
  .t-server,.t-lic,.t-up,.t-srv{grid-column:span 2;grid-row:auto;min-height:240px}
  .svc-grid{grid-template-columns:1fr 1fr}
  .svc,.svc:not(:nth-child(3n+1)){padding:28px 20px 28px 0;border-left:0}
  .why-grid{grid-template-columns:1fr 1fr;gap:32px}
  .why + .why{border-left:0;padding-left:0}
  .logos{grid-template-columns:repeat(3,1fr)}
  .foot{grid-template-columns:1fr 1fr}
  nav{display:none;position:absolute;left:0;right:0;top:76px;background:var(--paper);border-bottom:1px solid var(--line);padding:18px 24px}
  nav.open{display:block}
  nav ul{flex-direction:column;gap:14px}
  .menu-btn{display:block}
  .nav .btn-primary{display:none}
  .trial-box{padding:36px 26px}
  section{padding:68px 0}
}
@media(max-width:560px){
  .svc-grid,.why-grid,.two,.foot{grid-template-columns:1fr}
  .logos{grid-template-columns:repeat(2,1fr)}
  .strip .wrap{justify-content:center}
  .v-chip{display:none}
}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}

.sv-hero{background:linear-gradient(135deg,var(--violet-deep),var(--violet));color:#fff;padding:80px 0 88px;position:relative;overflow:hidden}
.sv-hero::after{content:"";position:absolute;right:-160px;top:-180px;width:560px;height:560px;border-radius:50%;background:radial-gradient(circle,rgba(31,194,216,.32),transparent 68%)}
.sv-hero .wrap{display:grid;grid-template-columns:1.15fr 1fr;gap:56px;align-items:center;position:relative;z-index:1}
.pill{display:inline-flex;gap:8px;align-items:center;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.25);padding:7px 14px;border-radius:999px;font-weight:600;font-size:13.5px;margin-bottom:22px}
.pill::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--aqua)}
.sv-hero h1{font-size:clamp(38px,5vw,62px);margin-bottom:20px}
.sv-hero h1 em{font-style:normal;color:var(--aqua)}
.sv-hero .lead{color:#CFC8F5;margin-bottom:14px;max-width:560px}
.btn-line{border-color:#fff;color:#fff}
.btn-line:hover{background:#fff;color:var(--violet-deep)}
.lock{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);border-radius:24px;padding:30px;backdrop-filter:blur(8px)}
.lock .pair{display:flex;align-items:center;gap:14px;justify-content:center;margin-bottom:22px}
.lock .co{background:#fff;color:var(--ink);border-radius:14px;padding:14px 18px;font:700 18px 'Bricolage Grotesque';text-align:center}
.lock .link{flex:1;height:2px;background:linear-gradient(90deg,var(--aqua),#fff);position:relative;min-width:40px}
.lock .link::after{content:"+";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);background:var(--violet);width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-weight:700}
.lock .three{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.lock .three div{border-top:3px solid var(--aqua);background:rgba(255,255,255,.08);border-radius:0 0 12px 12px;padding:12px 10px;font-size:13px;color:#CFC8F5}
.lock .three b{display:block;color:#fff;font:700 15px 'Bricolage Grotesque'}
.trust{background:var(--lav);padding:30px 0;border-bottom:1px solid var(--line)}
.trust .wrap{display:flex;gap:30px;align-items:center;justify-content:space-between;flex-wrap:wrap}
.trust p{max-width:420px;color:var(--muted);font-size:15.5px}
.trust p b{display:block;color:var(--ink);font:700 18px 'Bricolage Grotesque'}
.trust ul{display:flex;gap:12px 26px;flex-wrap:wrap;list-style:none;font-weight:600;font-size:15px}
.trust li::before{content:"✓";color:#fff;background:var(--violet);width:22px;height:22px;border-radius:50%;display:inline-grid;place-items:center;font-size:12px;margin-right:8px}
.part{display:grid;grid-template-columns:1fr 1.1fr;gap:60px;align-items:start}
.part h2{font-size:clamp(28px,3.6vw,42px);margin-bottom:14px}
.part p{color:var(--muted)}
.chips2{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:26px}
.chips2 span{background:#fff;border:1px solid var(--line);padding:9px 16px;border-radius:999px;font-weight:600;font-size:15px}
.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.facts div{background:var(--lav);border-radius:16px;padding:18px 16px}
.facts b{display:block;font:700 18px/1.15 'Bricolage Grotesque';margin-bottom:4px}
.facts span{color:var(--muted);font-size:14px}
.svc-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.sc{background:#fff;border:1px solid var(--line);border-radius:22px;overflow:hidden;transition:transform .25s,box-shadow .25s}
.sc:hover{transform:translateY(-4px);box-shadow:0 30px 50px -30px rgba(30,17,96,.4)}
.sc-top{height:130px;background:linear-gradient(135deg,var(--violet),var(--violet-deep));display:grid;place-items:center;font-size:46px}
.sc:nth-child(even) .sc-top{background:linear-gradient(135deg,#4B2FB8,var(--aqua))}
.sc-body{padding:24px 24px 28px}
.sc h3{font-size:22px;margin-bottom:8px}
.sc p{color:var(--muted);font-size:15.5px}
.how{background:var(--violet-deep);color:#fff}
.how .sec-head p{color:#CFC8F5}
.steps{display:grid;grid-template-columns:repeat(5,1fr);gap:22px;counter-reset:s;position:relative}
.steps::before{content:"";position:absolute;left:5%;right:5%;top:22px;height:2px;background:rgba(255,255,255,.2)}
.st{position:relative;text-align:center}
.st .n{width:46px;height:46px;border-radius:50%;background:var(--aqua);color:var(--violet-deep);font:800 20px 'Bricolage Grotesque';display:grid;place-items:center;margin:0 auto 16px;position:relative}
.st h3{font-size:18px;margin-bottom:8px}
.st p{color:#CFC8F5;font-size:14.5px}
.cta-end{background:var(--ink);color:#fff;text-align:center;padding:76px 0}
.cta-end h2{font-size:clamp(28px,3.6vw,42px);margin-bottom:12px}
.cta-end p{color:#B9B4D6;margin:0 auto 28px;max-width:600px}
.cta-end .cta-row{justify-content:center;margin:0}
@media(max-width:960px){
  .sv-hero .wrap,.part{grid-template-columns:1fr}
  .svc-cards{grid-template-columns:1fr 1fr}
  .steps{grid-template-columns:1fr;gap:26px}
  .steps::before{display:none}
  .st{text-align:left;display:grid;grid-template-columns:60px 1fr;gap:0 14px}
  .st .n{margin:0;grid-row:span 2}
}
@media(max-width:560px){.svc-cards{grid-template-columns:1fr}.facts{grid-template-columns:1fr}}

.crumb{font-size:14px;margin-bottom:18px;color:#CFC8F5}
.crumb a{color:var(--aqua);font-weight:600}
.btn-call{background:#E2552B;color:#fff}
.btn-call:hover{background:#c8461f}
.finder{background:#fff;color:var(--ink);border-radius:24px;padding:26px;box-shadow:0 40px 80px -40px rgba(0,0,0,.5)}
.finder h2{font-size:22px;margin-bottom:14px}
.fopt{display:grid;grid-template-columns:auto 1fr;gap:4px 14px;padding:14px 16px;border:1.5px solid var(--line);border-radius:14px;margin-bottom:10px;transition:border-color .2s,background .2s}
.fopt:hover{border-color:var(--violet);background:var(--lav)}
.fopt b{font:700 17px 'Bricolage Grotesque'}
.fopt span{color:var(--muted);font-size:14px;grid-column:2}
.fopt i{font-style:normal;grid-row:span 2;align-self:center;width:38px;height:38px;border-radius:10px;background:var(--lav);display:grid;place-items:center}
.stats4{background:var(--lav);border-bottom:1px solid var(--line);padding:22px 0}
.stats4 .wrap{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.stats4 div{font-weight:600;display:flex;align-items:center;gap:12px;font-size:15.5px}
.stats4 i{font-style:normal;width:40px;height:40px;border-radius:10px;background:#fff;display:grid;place-items:center;flex:none}
.trustp{max-width:760px}
.trustp h2{font-size:clamp(28px,3.6vw,40px);margin-bottom:14px}
.trustp p{color:var(--muted);font-size:18px}
.amc-what{display:grid;grid-template-columns:1fr 1.25fr;gap:60px;align-items:start}
.amc-what h2{font-size:clamp(28px,3.6vw,40px)}
.amc-what p{color:var(--muted);margin-bottom:16px}
.plans3{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.pl{background:#fff;border:1px solid var(--line);border-radius:24px;padding:32px 28px;display:flex;flex-direction:column;gap:12px;transition:transform .25s,box-shadow .25s}
.pl:hover{transform:translateY(-4px);box-shadow:0 30px 50px -30px rgba(30,17,96,.4)}
.pl .tag{font:600 13px 'JetBrains Mono',monospace;color:var(--violet);background:var(--lav);padding:5px 10px;border-radius:8px;align-self:flex-start}
.pl h3{font-size:28px}
.pl p{color:var(--muted);flex:1}
.gets{display:flex;flex-wrap:wrap;gap:14px}
