.dl-hero .wrap{display:grid;grid-template-columns:1.2fr 1fr;gap:56px;align-items:center}
.eyebrow{display:inline-flex;gap:8px;align-items:center;background:#fff;border:1px solid var(--line);padding:7px 14px;border-radius:999px;font-weight:600;font-size:13.5px;color:var(--violet);margin-bottom:20px}
.eyebrow::before{content:"★";color:var(--saffron)}
.dl-hero h1{font-size:clamp(34px,4.4vw,54px);margin-bottom:20px}
.dl-hero h1 em{font-style:normal;color:var(--violet)}
.dl-hero .lead{max-width:600px;margin-bottom:12px}
.chk5{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0 28px}
.chk5 span{background:#fff;border:1px solid var(--line);border-radius:999px;padding:8px 14px;font-weight:600;font-size:14.5px;display:inline-flex;gap:8px;align-items:center}
.chk5 span::before{content:"✓";width:20px;height:20px;border-radius:50%;background:var(--aqua);color:var(--violet-deep);font-size:12px;font-weight:800;display:grid;place-items:center}
.rel{background:#fff;border:1px solid var(--line);border-radius:26px;padding:30px;box-shadow:0 40px 80px -40px rgba(30,17,96,.4)}
.rel .ver{display:inline-block;font:800 14px 'JetBrains Mono',monospace;background:var(--violet);color:#fff;padding:5px 12px;border-radius:8px;margin-bottom:14px}
.rel h2{font-size:26px;margin-bottom:8px}
.rel > p{color:var(--muted);font-size:15.5px;margin-bottom:16px}
.rel ul{list-style:none;display:grid;gap:10px;font-size:15px}
.rel li{display:flex;gap:10px}
.rel li::before{content:"✓";color:#13744F;font-weight:800}
.trial2{background:var(--aqua-soft);border-radius:28px;padding:56px 40px;text-align:center}
.trial2 .tag{display:inline-block;background:#fff;border-radius:999px;padding:7px 16px;font-weight:600;font-size:14px;margin-bottom:16px}
.trial2 h2{font-size:clamp(28px,3.6vw,40px);margin-bottom:12px}
.trial2 p{max-width:600px;margin:0 auto 24px;color:var(--muted);font-size:18px}
.gd{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.gs{background:#fff;border:1px solid var(--line);border-radius:20px;padding:26px 22px;position:relative}
.gs .n{width:40px;height:40px;border-radius:50%;background:var(--violet);color:#fff;font:800 18px 'Bricolage Grotesque';display:grid;place-items:center;margin-bottom:14px}
.gs h3{font-size:21px;margin-bottom:6px}
.gs p{color:var(--muted);font-size:15px}
.req{background:var(--lav);border-radius:28px;padding:48px 40px}
.reqg{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}
.rq{background:#fff;border-radius:18px;padding:22px 18px}
.rq i{font-style:normal;font-size:26px;display:block;margin-bottom:10px}
.rq b{font:700 18px 'Bricolage Grotesque';display:block;margin-bottom:6px}
.rq span{color:var(--muted);font-size:14.5px}
.new8{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.nw{background:#fff;border:1px solid var(--line);border-radius:20px;padding:24px 22px;transition:transform .25s,box-shadow .25s}
.nw:hover{transform:translateY(-4px);box-shadow:0 30px 50px -30px rgba(30,17,96,.4)}
.nw i{font-style:normal;width:46px;height:46px;border-radius:13px;background:var(--lav);display:grid;place-items:center;font-size:22px;margin-bottom:14px}
.nw:nth-child(even) i{background:var(--aqua-soft)}
.nw h3{font-size:19px;margin-bottom:6px;line-height:1.15}
.nw p{color:var(--muted);font-size:14.5px}
.why10{background:var(--ink);color:#fff;border-radius:28px;padding:48px 44px}
.why10 h2{font-size:clamp(28px,3.4vw,38px);margin-bottom:8px}
.why10 > p{color:#B9B4D6;margin-bottom:26px}
.why10 ul{list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:16px 40px}
.why10 li{display:flex;gap:12px;font-weight:600}
.why10 li::before{content:"✓";flex:none;width:24px;height:24px;border-radius:50%;background:var(--aqua);color:var(--violet-deep);font-size:13px;font-weight:800;display:grid;place-items:center}
.faq-s{max-width:820px;margin:0 auto}
.cta-box{background:var(--aqua-soft);border-radius:28px;padding:56px 40px;text-align:center}
.cta-box h2{font-size:clamp(28px,3.6vw,40px);margin-bottom:12px}
.cta-box p{max-width:720px;margin:0 auto 26px;color:var(--muted);font-size:17px}
.cta-box .cta-row{justify-content:center;margin:0}
@media(max-width:960px){.dl-hero .wrap{grid-template-columns:1fr}.gd,.new8{grid-template-columns:1fr 1fr}.reqg{grid-template-columns:1fr 1fr}.why10 ul{grid-template-columns:1fr}.req,.trial2,.why10,.cta-box{padding:34px 24px}}
@media(max-width:560px){.gd,.new8,.reqg{grid-template-columns:1fr}}
